//! The engine boundary: the only module allowed `unsafe` code and the only
//! one the engine calls into (ARCHITECTURE.md L0).
//!
//! It wraps the engine's C declarations in `crate::bindings` (generated by
//! bindgen from upstream's headers, engine/bindings/generate.sh) into a few
//! safe functions. Every symbol it uses is listed, with its reason, in
//! docs/ENGINE-READS.md (the D3 audit, docs/SPEC.md §5).
//!
//! The engine is single-threaded and calls the Borg only from its own
//! thread: through `do_cmd_borg` (the `^Z` command) and through the
//! `inkey_hack` hook while the Borg runs. Nothing here is called from
//! anywhere else.
#![allow(unsafe_code)]

use crate::bindings as b;
use core::ffi::{c_char, c_int, CStr};

/// `ESCAPE` (ui-event.h).
pub const ESCAPE: u32 = 0xE000;
/// `KC_ENTER` (ui-event.h).
pub const KC_ENTER: u32 = 0x9c;

/// What the Borg reads of the player each think (spec §1.1, channel B).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PlayerView {
    pub hp: i32,
    pub max_hp: i32,
    pub x: i32,
    pub y: i32,
    pub depth: i32,
    pub dead: bool,
    /// The game is resting, or repeating a command: the Borg must not
    /// interrupt it (spec §2.7).
    pub busy: bool,
    /// The engine's game turn.
    pub turn: i64,
}

/// The player's state, or `None` before a character exists.
pub fn player_view() -> Option<PlayerView> {
    // SAFETY: engine globals, read on the engine thread between game steps;
    // `player` and its `upkeep` are allocated once a character exists.
    unsafe {
        let p = b::player;
        if p.is_null() || (*p).upkeep.is_null() {
            return None;
        }
        let p = &*p;
        Some(PlayerView {
            hp: p.chp as i32,
            max_hp: p.mhp as i32,
            x: p.grid.x,
            y: p.grid.y,
            depth: p.depth as i32,
            dead: p.is_dead,
            busy: (*p.upkeep).resting != 0 || b::cmd_get_nrepeats() > 0,
            turn: b::turn as i64,
        })
    }
}

/// The terrain the player knows at a grid (`map_info`), as a feature index
/// of `list-terrain.h`, or `None` outside the level.
pub fn known_feature(x: i32, y: i32) -> Option<u32> {
    // SAFETY: `cave` is the current level; `square_in_bounds_fully` checks
    // the grid before `map_info` reads it; `grid_data` is plain data.
    unsafe {
        let c = b::cave;
        if c.is_null() {
            return None;
        }
        let grid = b::loc { x, y };
        if !b::square_in_bounds_fully(c, grid) {
            return None;
        }
        let mut g: b::grid_data = core::mem::zeroed();
        b::map_info(grid, &mut g);
        Some(g.f_idx)
    }
}

/// The game's whole RNG state (z-rand.c): the quick flag and value, and the
/// complex generator's index and state.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct GameRng {
    quick: bool,
    value: u32,
    index: u32,
    state: [u32; 32],
}

/// A snapshot of the game's RNG.
pub fn game_rng() -> GameRng {
    // SAFETY: plain engine globals, read on the engine thread.
    unsafe {
        GameRng {
            quick: b::Rand_quick,
            value: b::Rand_value,
            index: b::state_i,
            state: b::STATE,
        }
    }
}

fn set_game_rng(r: &GameRng) {
    // SAFETY: as above; restores values read by `game_rng`.
    unsafe {
        b::Rand_quick = r.quick;
        b::Rand_value = r.value;
        b::state_i = r.index;
        b::STATE = r.state;
    }
}

/// Run engine reads with the Borg's own RNG (spec §1.2; RULES 10): the
/// game's RNG is saved, the quick generator is seeded with `borg_value`, and
/// afterwards `borg_value` keeps the Borg's advanced value and the game's
/// whole RNG is restored. Engine reads can draw: `map_info()` does so for a
/// hallucinating player (cave-map.c, `one_in_(128)`). This is the C Borg's
/// swap in `generate_keypress()` (borg.c:355-374), extended to the whole
/// state.
pub fn with_borg_rng<T>(borg_value: &mut u32, f: impl FnOnce() -> T) -> T {
    /// Restores the game's RNG when dropped, so it is restored on every
    /// path out of `f`, a panic included (M2 review C5).
    struct Restore(GameRng);
    impl Drop for Restore {
        fn drop(&mut self) {
            set_game_rng(&self.0);
        }
    }
    let saved = Restore(game_rng());
    // SAFETY: plain engine globals; restored by `saved`.
    unsafe {
        b::Rand_quick = true;
        b::Rand_value = *borg_value;
    }
    let out = f();
    // SAFETY: as above.
    *borg_value = unsafe { b::Rand_value };
    drop(saved);
    out
}

/// Test builds only (cargo feature `test-hallucinate`): make the player
/// hallucinate for the duration of `f`, then restore the timer exactly.
/// Used by the RNG-isolation regression (CI): perception then takes the
/// random `map_info()` path on every think.
#[cfg(feature = "test-hallucinate")]
pub fn while_hallucinating<T>(f: impl FnOnce() -> T) -> T {
    // SAFETY: `player->timed` has TMD_MAX entries; the value is restored.
    unsafe {
        let p = b::player;
        if p.is_null() || (*p).timed.is_null() {
            return f();
        }
        let slot = (*p).timed.add(b::TMD_IMAGE as usize);
        let old = *slot;
        *slot = 100;
        let out = f();
        *slot = old;
        out
    }
}

/// Read the `^Z` command key ("Borg command"), or `None` if cancelled.
pub fn read_command() -> Option<u8> {
    let mut ch: c_char = 0;
    // SAFETY: `get_com` writes one char; the prompt is a static C string.
    let ok = unsafe { b::get_com(c"Borg command: ".as_ptr(), &mut ch) };
    ok.then_some(ch as u8)
}

/// A real key the user pressed (or a terminal disconnect), taken from the
/// terminal's queue without waiting: the C Borg's `user_abort` (spec §2.2
/// step 8). `None` when nothing is pending, as always under borgh after its
/// start script.
pub fn take_user_key() -> Option<u32> {
    // SAFETY: `ui_event` is a C union of plain-data structs that all start
    // with the type; `Term_inkey` zeroes it first, so reading the key
    // variant is defined (as in borg-rs's `term_inkey`).
    let (kind, code) = unsafe {
        let mut ev: b::ui_event = core::mem::zeroed();
        b::Term_inkey(&mut ev, false, true);
        (ev.type_, ev.key.code)
    };
    let keyboard = kind & b::EVT_KBRD != 0 && code > 0 && code != 10;
    (keyboard || kind == b::EVT_DISCONNECT).then_some(code)
}

/// Set a game option by name; false if the engine does not know it.
pub fn set_option(name: &CStr, on: bool) -> bool {
    // SAFETY: `option_set` looks the name up in the option table.
    unsafe { b::option_set(name.as_ptr(), on as c_int) }
}

extern "C" {
    /// `ui-input.c:130`. Upstream declares it in no header (its Windows
    /// frontend declares it itself, `main-win.c:3298`), so it is not in the
    /// generated bindings.
    static mut inkey_hack: Option<unsafe extern "C" fn(flush_first: c_int) -> b::keypress>;
}

/// Install or remove the Borg's keypress hook.
pub fn set_hook(on: bool) {
    // SAFETY: `inkey_hack` is read by the engine's key reader on this thread.
    unsafe {
        inkey_hack = if on { Some(inkey_hook) } else { None };
    }
}

/// Tell the headless harness that the Borg made a decision (borgh's stall
/// detection and progress states). Only in harness builds: the symbol
/// exists only in the `borgh` frontend.
#[cfg(feature = "borgh")]
pub fn report_decision(rng: u32) {
    extern "C" {
        fn borgh_decision(rng: u32);
    }
    // SAFETY: a plain call into borgh, which copies the value.
    unsafe { borgh_decision(rng) }
}

/// See the harness-build version above; a no-op in other builds.
#[cfg(not(feature = "borgh"))]
pub fn report_decision(_rng: u32) {}

/// The keypress the engine receives.
pub enum Key {
    /// A key code (`EVT_KBRD`).
    Code(u32),
    /// Nothing (`EVT_NONE`): let the game's own rest or repeat run.
    None,
}

/// The `inkey_hack` callback: the engine wants a key.
extern "C" fn inkey_hook(flush_first: c_int) -> b::keypress {
    let key = crate::borg::next_key(flush_first != 0);
    let (type_, code) = match key {
        Key::Code(c) => (b::EVT_KBRD, c),
        Key::None => (b::EVT_NONE, 0),
    };
    b::keypress {
        type_,
        code,
        mods: 0,
    }
}

/// The engine's call into the Borg commands (`^Z`, `do_cmd_try_borg` in
/// `angband/src/cmd-misc.c`).
#[no_mangle]
extern "C" fn do_cmd_borg() {
    // The decision core (#207, the option-C pilot): borg-rs's, vendored at
    // its pin in `borg-core/`, when `BORG_CORE=borg-rs`; ours otherwise.
    if crate::borg::core_is_borg_rs() {
        borg_rs::do_cmd_borg();
        return;
    }
    crate::borg::command();
}

// ---------------------------------------------------------------------------
// Perception (L1, task T2.1): the reads behind an `Observation`.

use crate::observation::{
    parse_messages, Grid, Item, MonsterSeen, ObjectSeen, Observation, Panel, Slot, Spell, Status,
    StoreStock, Ware,
};

/// The text of screen row `row`, columns `col..col + len` (all of the row
/// if `len` is `None`), trailing blanks removed: `borg_what_text()`'s read
/// of the terminal buffer (channel A).
fn screen_text(row: i32, col: i32, len: Option<i32>) -> String {
    // SAFETY: `Term` and its `scr` window are allocated by the frontend
    // before the Borg runs; rows and columns are checked against its size.
    unsafe {
        let t = b::Term;
        if t.is_null() || (*t).scr.is_null() || row < 0 || row >= (*t).hgt {
            return String::new();
        }
        let wid = (*t).wid;
        let end = len.map_or(wid, |l| (col + l).min(wid));
        let line = *(*(*t).scr).c.add(row as usize);
        let s: String = (col.max(0)..end)
            .map(|x| char::from_u32(*line.add(x as usize) as u32).unwrap_or('?'))
            .collect();
        s.trim_end().to_string()
    }
}

/// The message line as the prompt catcher reads it (channel A): row 0's
/// text, whether its first text cell carries the dark attribute
/// (`COLOUR_DARK`, z-color.h:23 — a blank or undrawn line), and the
/// terminal cursor (`Term_locate`, ui-term.c:2477-2488, read as the C
/// Borg does at borg.c:278-279).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct MessageLine {
    pub text: String,
    pub dark: bool,
    pub cursor: (i32, i32),
}

/// Read the message line for the prompt catcher (executor).
pub fn message_line() -> MessageLine {
    // SAFETY: as `screen_text`; the cursor fields are plain ints of the
    // screen window, and the attribute row is indexed within the width.
    unsafe {
        let t = b::Term;
        if t.is_null() || (*t).scr.is_null() {
            return MessageLine::default();
        }
        let scr = &*(*t).scr;
        let text = screen_text(0, 0, None);
        // The attribute of the first non-space cell, as borg_what_text
        // reports the span's attribute (borg-io.c:87-123): dark when the
        // row holds nothing but spaces or its first text cell is dark.
        let mut dark = true;
        if !scr.a.is_null() && !scr.c.is_null() && (*t).wid > 0 {
            let attrs = *scr.a.add(0);
            let cells = *scr.c.add(0);
            if !attrs.is_null() && !cells.is_null() {
                for x in 0..(*t).wid as usize {
                    let ch = char::from_u32(*cells.add(x) as u32).unwrap_or(' ');
                    if ch != ' ' {
                        dark = *attrs.add(x) == 0;
                        break;
                    }
                }
            }
        }
        MessageLine {
            text,
            dark,
            cursor: (scr.cx, scr.cy),
        }
    }
}

/// Whether the game is waiting for a command in the main interface
/// (`inkey_flag`, ui-input.c:54): the C Borg's test for a line that needs
/// an answer now rather than a message to parse (borg-messages.c:218).
pub fn wants_command() -> bool {
    // SAFETY: a plain engine global, read on the engine thread.
    unsafe { b::inkey_flag }
}

/// The C Borg's item analysis of one object (`borg_item_analyze`). In a
/// shop (`in_store`) the player is always aware of the flavour, and the
/// description is the store's (`ODESC_STORE`).
///
/// # Safety
/// `obj` is a live object of the player's gear or a store.
unsafe fn analyze(obj: *const b::object, in_store: bool) -> Option<Item> {
    let o = &*obj;
    if o.kind.is_null() || o.number == 0 {
        return None;
    }
    // The engine's knowledge functions dereference `obj->known`
    // (`object_flags_known`, obj-util.c:364-368): gear and wares always have
    // one; an object without is not analysed (E review, nit).
    if o.known.is_null() {
        return None;
    }
    let fully_known = b::object_fully_known(obj);
    let k = if fully_known { o } else { &*o.known };
    let mut flags = [0u8; 5];
    b::object_flags_known(obj, flags.as_mut_ptr());
    let mut buf = [0 as c_char; 256];
    b::object_desc(
        buf.as_mut_ptr(),
        buf.len(),
        obj,
        b::ODESC_FULL | if in_store { b::ODESC_STORE } else { 0 },
        b::player,
    );
    Some(Item {
        kind: (*o.kind).kidx,
        tval: o.tval,
        sval: o.sval,
        number: o.number,
        weight: b::object_weight_one(obj),
        timeout: o.timeout,
        level: (*o.kind).level,
        desc: CStr::from_ptr(buf.as_ptr()).to_string_lossy().into_owned(),
        aware: in_store || b::object_flavor_is_aware(obj),
        fully_known,
        runes_known: b::object_runes_known(obj),
        flags,
        ac: k.ac,
        dd: k.dd,
        ds: k.ds,
        to_h: k.to_h,
        to_d: k.to_d,
        to_a: k.to_a,
        modifiers: k.modifiers.to_vec(),
        elements: k.el_info.iter().map(|e| (e.res_level, e.flags)).collect(),
    })
}

/// The top object on a floor grid that is not ignored, as
/// `borg-flow-take.c:borg_get_top_object:50-64` picks it.
///
/// # Safety
/// `c` is the current level and `grid` is in bounds.
unsafe fn top_object_kind(c: *mut b::chunk, grid: b::loc) -> Option<u32> {
    let mut o = b::square_object(c, grid);
    while !o.is_null() {
        let ignored = (!(*o).known.is_null()
            && (*(*o).known).notice & b::OBJ_NOTICE_IGNORE as u8 != 0)
            || (*(*o).kind).ignore != 0;
        if !ignored {
            return Some((*(*o).kind).kidx);
        }
        o = (*o).next;
    }
    None
}

/// Perceive: one `Observation` of everything the C Borg's two channels give
/// it (spec §1.1). `None` before a character and a level exist. Run it with
/// the Borg's RNG (`with_borg_rng`): `map_info()` can draw.
pub fn perceive() -> Option<Observation> {
    // SAFETY: engine globals read on the engine thread between game steps.
    // `player`, its `upkeep`, `timed`, gear arrays and body are allocated
    // once a character exists; `cave` once a level exists. Every array is
    // read within the sizes the engine gives (`z_info`, `body.count`,
    // `TMD_MAX`, `MON_TMD_MAX`, `total_spells`), and every grid is checked
    // with `square_in_bounds_fully` first.
    unsafe {
        let p = b::player;
        let c = b::cave;
        let z = b::z_info;
        let t = b::Term;
        if p.is_null()
            || (*p).upkeep.is_null()
            || (*p).timed.is_null()
            || c.is_null()
            || z.is_null()
            || t.is_null()
        {
            return None;
        }
        let pl = &*p;
        let up = &*pl.upkeep;

        let status = Status {
            race: if pl.race.is_null() {
                0
            } else {
                (*pl.race).ridx
            },
            class: if pl.class.is_null() {
                0
            } else {
                (*pl.class).cidx
            },
            x: pl.grid.x,
            y: pl.grid.y,
            depth: pl.depth as i32,
            max_depth: pl.max_depth as i32,
            level: pl.lev as i32,
            max_level: pl.max_lev as i32,
            exp: pl.exp,
            max_exp: pl.max_exp,
            gold: pl.au,
            hp: pl.chp as i32,
            max_hp: pl.mhp as i32,
            sp: pl.csp as i32,
            max_sp: pl.msp as i32,
            stat_cur: pl.stat_cur,
            stat_max: pl.stat_max,
            stat_use: pl.state.stat_use,
            stat_ind: pl.state.stat_ind,
            speed: pl.state.speed,
            blows: pl.state.num_blows,
            percent_damage: pl.opts.opt[b::OPT_birth_percent_damage as usize],
            known_ac: pl.known_state.ac + pl.known_state.to_a,
            timed: (0..b::TMD_MAX as usize).map(|i| *pl.timed.add(i)).collect(),
            word_recall: pl.word_recall as i32,
            deep_descent: pl.deep_descent as i32,
            new_spells: up.new_spells,
            food: pl.timed.add(b::TMD_FOOD as usize).read() as i32,
            pack_used: b::pack_slots_used(p),
            pack_size: i32::from((*z).pack_size),
            busy: up.resting != 0 || up.running != 0 || b::cmd_get_nrepeats() > 0,
            dead: pl.is_dead,
            winner: pl.total_winner != 0,
            in_vault: b::square_in_bounds_fully(c, pl.grid) && b::square_isvault(c, pl.grid),
        };

        let mut equipment = Vec::new();
        let mut slot = pl.body.slots;
        for _ in 0..pl.body.count {
            if slot.is_null() {
                break;
            }
            let s = &*slot;
            equipment.push(Slot {
                slot_type: s.type_,
                item: if s.obj.is_null() {
                    None
                } else {
                    analyze(s.obj, false)
                },
            });
            slot = slot.add(1);
        }
        let list = |arr: *mut *mut b::object, n: u16| -> Vec<Item> {
            if arr.is_null() {
                return Vec::new();
            }
            (0..n as usize)
                .map(|i| *arr.add(i))
                .filter(|o| !o.is_null())
                .filter_map(|o| analyze(o, false))
                .collect()
        };
        let quiver = list(up.quiver, (*z).quiver_size);
        // The pack has pack_size + 1 entries: it may be overfull by one
        // (player.c:495, player-calcs.c:1019-1022; M2 third review, 1).
        let inventory = list(up.inven, (*z).pack_size + 1);

        let mut spells = Vec::new();
        if !pl.class.is_null() && !pl.spell_flags.is_null() {
            let magic = &(*pl.class).magic;
            for i in 0..magic.total_spells {
                let sp = b::spell_by_index(p, i);
                if sp.is_null() {
                    continue;
                }
                spells.push(Spell {
                    book: (*sp).bidx,
                    level: (*sp).slevel,
                    mana: (*sp).smana,
                    base_fail: (*sp).sfail,
                    flags: *pl.spell_flags.add(i as usize),
                    fail: i32::from(b::spell_chance(i)),
                    aim: b::spell_needs_aim(i),
                    damage: spell_damage((*sp).effect),
                    nourish: spell_nourishes((*sp).effect),
                });
            }
        }

        // The map panel: SCREEN_HGT x SCREEN_WID grids from the term's
        // offset (ui-term.h), clipped to the level.
        let term = &*t;
        let mode = (term.sidebar_mode as usize).min(2);
        let screen_hgt = (term.hgt - b::row_top_map[mode] - b::row_bottom_map[mode])
            / i32::from(b::tile_height).max(1);
        let screen_wid = (term.wid - b::col_map[mode] - 1) / i32::from(b::tile_width).max(1);
        let (lw, lh) = ((*c).width, (*c).height);
        let (x0, y0) = (term.offset_x.max(0), term.offset_y.max(0));
        let width = screen_wid.min(lw - x0).max(0);
        let height = screen_hgt.min(lh - y0).max(0);
        let mut grids = Vec::with_capacity((width * height) as usize);
        let mut monsters = Vec::new();
        let mut objects = Vec::new();
        for y in y0..y0 + height {
            for x in x0..x0 + width {
                let grid = b::loc { x, y };
                if !b::square_in_bounds_fully(c, grid) {
                    grids.push(Grid {
                        feat: 0,
                        in_view: false,
                        lighting: 0,
                        monster: false,
                        object_kind: None,
                        multiple_objects: false,
                        unseen_object: false,
                        unseen_money: false,
                        trap: false,
                        shop: -1,
                        webbed: false,
                    });
                    continue;
                }
                let mut g: b::grid_data = core::mem::zeroed();
                b::map_info(grid, &mut g);
                // A hallucinating player sees fabricated display data on an
                // empty grid: `m_idx = 1` or `first_kind = k_info`, the unused
                // kind 0 (cave-map.c:178-186; E review, finding 2). Only real
                // data is observed: a visible monster whose own grid is this
                // one, an object of a real kind. Visibility is map_info's own
                // test: monster 1 may stand unseen on the grid where a
                // hallucination puts `m_idx = 1` (T2.5).
                let object_kind = (!g.first_kind.is_null())
                    .then(|| (*g.first_kind).kidx)
                    .filter(|&k| k != 0);
                let monster = if g.m_idx > 0 {
                    let m = b::cave_monster(c, g.m_idx as c_int);
                    (!m.is_null()
                        && !(*m).race.is_null()
                        && (*m).grid.x == x
                        && (*m).grid.y == y
                        && b::monster_is_visible(m))
                    .then_some(m)
                } else {
                    None
                };
                if let Some(m) = monster {
                    let m = &*m;
                    monsters.push(MonsterSeen {
                        index: m.midx,
                        x,
                        y,
                        race: (*m.race).ridx,
                        hp: m.hp as i32,
                        max_hp: m.maxhp as i32,
                        timed: m.m_timed,
                        speed: m.mspeed,
                        attr: m.attr,
                        mimicking: !m.mimicked_obj.is_null(),
                    });
                }
                if object_kind.is_some() {
                    objects.push(ObjectSeen {
                        x,
                        y,
                        kind: top_object_kind(c, grid),
                    });
                }
                grids.push(Grid {
                    feat: g.f_idx,
                    in_view: g.in_view,
                    lighting: g.lighting,
                    monster: monster.is_some(),
                    object_kind,
                    multiple_objects: g.multiple_objects,
                    unseen_object: g.unseen_object,
                    unseen_money: g.unseen_money,
                    trap: !g.trap.is_null(),
                    // Both read the real cave: only where the player knows
                    // the feature, as the C Borg guards them (borg-update.c:
                    // 317, a known shop; :542, a known floor). An unknown
                    // grid says nothing (M2 review, finding 1).
                    shop: if g.f_idx != 0 && b::feat_is_shop(g.f_idx as c_int) {
                        b::square_shopnum(c, grid)
                    } else {
                        -1
                    },
                    webbed: g.f_idx == b::FEAT_FLOOR && b::square_iswebbed(c, grid),
                });
            }
        }
        // Every store's stock (borg_notice_store). The home's wares are
        // analysed as gear, not as shop wares (`in_store` false), as there.
        let mut stores = Vec::new();
        let home = 7;
        let st = b::stores;
        let max_wares = usize::from((*z).store_inven_max);
        if !st.is_null() {
            let mut list: Vec<*mut b::object> = vec![core::ptr::null_mut(); max_wares];
            for n in 0..i32::from((*z).store_max) {
                let store = st.add(n as usize);
                list.iter_mut().for_each(|o| *o = core::ptr::null_mut());
                b::store_stock_list(store, list.as_mut_ptr(), max_wares as c_int);
                let wares = list
                    .iter()
                    .take_while(|o| !o.is_null())
                    .filter_map(|&o| {
                        let item = analyze(o, n != home)?;
                        (item.desc != "(nothing)").then(|| Ware {
                            price: if n == home {
                                0
                            } else {
                                b::price_item(store, o, false, 1)
                            },
                            item,
                        })
                    })
                    .collect();
                stores.push(StoreStock { number: n, wares });
            }
        }
        let message_line = screen_text(0, 0, None);
        Some(Observation {
            turn: b::turn as i64,
            status,
            equipment,
            quiver,
            inventory,
            spells,
            panel: Panel {
                x0,
                y0,
                width,
                height,
                level_width: lw,
                level_height: lh,
                grids,
            },
            messages: parse_messages(&message_line),
            message_line,
            store_header: screen_text(3, 1, Some(4)),
            monsters,
            objects,
            stores,
        })
    }
}

// ---------------------------------------------------------------------------
// Knowledge (L3, task T2.3): the engine's parsed game data, read once.

use crate::knowledge::{
    Artifact, Blow, Book, Class, ClassSpell, Dice, Ego, Knowledge, MonsterRace, ObjectKind,
    PlayerRace, StoreKind,
};

fn text(p: *const c_char) -> String {
    if p.is_null() {
        return String::new();
    }
    // SAFETY: the engine's names are NUL-terminated C strings that live as
    // long as the game data.
    unsafe { CStr::from_ptr(p).to_string_lossy().into_owned() }
}

fn dice(r: &b::random_value) -> Dice {
    Dice {
        base: r.base,
        dice: r.dice,
        sides: r.sides,
        m_bonus: r.m_bonus,
    }
}

fn elements(e: &[b::element_info]) -> Vec<(i16, u8)> {
    e.iter().map(|x| (x.res_level, x.flags)).collect()
}

/// Read the game's static data (L3). `None` before the game data is loaded.
/// It only reads: the arrays are indexed within `z_info`'s counts, and the
/// lists (classes, b::races, blows, books, store tables) end where the engine
/// ends them.
pub fn knowledge() -> Option<Knowledge> {
    // SAFETY: engine globals read on the engine thread after the game data
    // is parsed (the Borg runs only inside a game); see above for bounds.
    unsafe {
        let z = b::z_info;
        if z.is_null() || b::r_info.is_null() || b::k_info.is_null() {
            return None;
        }
        let z = &*z;
        let mut k = Knowledge {
            extract_energy: b::extract_energy.to_vec(),
            move_energy: i32::from(z.move_energy),
            adj_str_blow: b::adj_str_blow.to_vec(),
            adj_str_hold: b::adj_str_hold.to_vec(),
            ..Default::default()
        };
        for i in 0..usize::from(z.r_max) {
            let r = &*b::r_info.add(i);
            let mut blows = Vec::new();
            let mut b = r.blow;
            while !b.is_null() && !(*b).method.is_null() {
                let bl = &*b;
                blows.push(Blow {
                    method: text((*bl.method).name),
                    effect: if bl.effect.is_null() {
                        String::new()
                    } else {
                        text((*bl.effect).name)
                    },
                    power: if bl.effect.is_null() {
                        0
                    } else {
                        (*bl.effect).power
                    },
                    dice: dice(&bl.dice),
                });
                b = bl.next;
            }
            k.races.push(MonsterRace {
                index: r.ridx,
                name: text(r.name),
                base: if r.base.is_null() {
                    String::new()
                } else {
                    text((*r.base).name)
                },
                level: r.level,
                rarity: r.rarity,
                speed: r.speed,
                avg_hp: r.avg_hp,
                ac: r.ac,
                sleep: r.sleep,
                hearing: r.hearing,
                smell: r.smell,
                exp: r.mexp,
                freq_innate: r.freq_innate,
                freq_spell: r.freq_spell,
                spell_power: r.spell_power,
                flags: r.flags.to_vec(),
                spell_flags: r.spell_flags.to_vec(),
                blows,
                glyph: r.d_char as u32,
                attr: r.d_attr,
            });
        }
        for i in 0..usize::from(z.k_max) {
            let o = &*b::k_info.add(i);
            k.kinds.push(ObjectKind {
                index: o.kidx,
                name: text(o.name),
                tval: o.tval,
                sval: o.sval,
                level: o.level,
                cost: o.cost,
                weight: o.weight,
                ac: o.ac,
                dd: o.dd,
                ds: o.ds,
                to_h: dice(&o.to_h),
                to_d: dice(&o.to_d),
                to_a: dice(&o.to_a),
                pval: dice(&o.pval),
                flags: o.flags.to_vec(),
                kind_flags: o.kind_flags.to_vec(),
                elements: elements(&o.el_info),
            });
        }
        if !b::e_info.is_null() {
            for i in 0..usize::from(z.e_max) {
                let e = &*b::e_info.add(i);
                k.egos.push(Ego {
                    index: e.eidx,
                    name: text(e.name),
                    cost: e.cost,
                    rating: e.rating,
                    flags: e.flags.to_vec(),
                    to_h: dice(&e.to_h),
                    to_d: dice(&e.to_d),
                    to_a: dice(&e.to_a),
                    modifiers: e.modifiers.iter().map(dice).collect(),
                    elements: elements(&e.el_info),
                });
            }
        }
        if !b::a_info.is_null() {
            for i in 0..usize::from(z.a_max) {
                let a = &*b::a_info.add(i);
                k.artifacts.push(Artifact {
                    index: a.aidx,
                    name: text(a.name),
                    tval: a.tval,
                    sval: a.sval,
                    level: a.level,
                    cost: a.cost,
                    weight: a.weight,
                    ac: a.ac,
                    dd: a.dd,
                    ds: a.ds,
                    to_h: a.to_h,
                    to_d: a.to_d,
                    to_a: a.to_a,
                    flags: a.flags.to_vec(),
                    modifiers: a.modifiers.to_vec(),
                    elements: elements(&a.el_info),
                });
            }
        }
        let mut c = b::classes;
        while !c.is_null() {
            let cl = &*c;
            let m = &cl.magic;
            let mut books = Vec::new();
            for bi in 0..m.num_books.max(0) as usize {
                let b = &*m.books.add(bi);
                let spells = (0..b.num_spells.max(0) as usize)
                    .map(|si| {
                        let s = &*b.spells.add(si);
                        ClassSpell {
                            index: s.sidx,
                            name: text(s.name),
                            level: s.slevel,
                            mana: s.smana,
                            fail: s.sfail,
                            exp: s.sexp,
                        }
                    })
                    .collect();
                books.push(Book {
                    tval: b.tval,
                    sval: b.sval,
                    dungeon: b.dungeon,
                    spells,
                });
            }
            k.classes.push(Class {
                index: cl.cidx,
                name: text(cl.name),
                stat_adj: cl.c_adj,
                skills: cl.c_skills,
                hit_die: cl.c_mhp,
                max_attacks: cl.max_attacks,
                min_weight: cl.min_weight,
                att_multiply: cl.att_multiply,
                spell_first: m.spell_first,
                spell_weight: m.spell_weight,
                books,
                pflags: cl.pflags.to_vec(),
            });
            c = cl.next;
        }
        k.classes.sort_by_key(|c| c.index);
        let mut r = b::races;
        while !r.is_null() {
            let ra = &*r;
            k.player_races.push(PlayerRace {
                index: ra.ridx,
                name: text(ra.name),
                stat_adj: ra.r_adj,
                skills: ra.r_skills,
                hit_die: ra.r_mhp,
                exp_factor: ra.r_exp,
                infravision: ra.infra,
                elements: elements(&ra.el_info),
            });
            r = ra.next;
        }
        k.player_races.sort_by_key(|r| r.index);
        if !b::stores.is_null() {
            for n in 0..usize::from(z.store_max) {
                let s = &*b::stores.add(n);
                let kinds = |t: *mut *mut b::object_kind, len: usize| -> Vec<u32> {
                    if t.is_null() {
                        return Vec::new();
                    }
                    (0..len)
                        .map(|i| *t.add(i))
                        .filter(|p| !p.is_null())
                        .map(|p| (*p).kidx)
                        .collect()
                };
                k.stores.push(StoreKind {
                    number: n as i32,
                    always: kinds(s.always_table, s.always_num),
                    normal: kinds(s.normal_table, s.normal_num),
                });
            }
        }
        Some(k)
    }
}

// ===========================================================================
// ENGINE TRUTH (feature test-perception; task T2.5, #16). Test builds only.
//
// Perception checked against the engine through routes other than the
// observation's own reads (docs/ENGINE-READS.md, reason T): the engine's own
// panel test (`panel_contains`), the player's map memory (`player->cave`),
// the whole monster list with the engine's visibility, and the gear list.
// Nothing here is compiled into the Borg that plays, and nothing here changes
// the game: it only reads, and it draws from no RNG. `engine/tests/
// test_reads.py` checks that the reason-T symbols appear only below this line.

#[cfg(feature = "test-perception")]
pub mod truth {
    use super::b;
    use crate::observation::{Item, Observation};
    use crate::world::World;
    use core::ffi::c_int;
    use serde::Serialize;

    /// `TV_SHOT`, `TV_ARROW`, `TV_BOLT` (list-tvals.h): ammunition.
    const AMMO: [u8; 3] = [2, 3, 4];

    /// One think's comparison. `differences` are disagreements with the
    /// engine; the counts are what was compared, and what the Borg does not
    /// see by design: the world beyond the map panel (the C Borg reads only
    /// the panel too, `borg-update.c:264`).
    #[derive(Debug, Default, Serialize)]
    pub struct Report {
        pub turn: i64,
        /// The status the frontend's state.log also writes, for
        /// tools/check-perception.py.
        pub state: State,
        /// Panel grids, by the engine's own panel test.
        pub panel_grids: u32,
        /// Grids the world remembers, compared with the player's memory.
        pub map_compared: u32,
        /// Grids the world remembers off the panel whose memory changed
        /// since the Borg saw them (declared: the panel limit).
        pub map_stale_off_panel: u32,
        /// Grids the player knows off the panel that the world never saw
        /// (declared: the panel limit; detection and mapping beyond it).
        /// On the panel, such a grid is a difference.
        pub map_unknown_to_world: u32,
        /// Visible monsters on the panel, compared field by field.
        pub monsters_compared: u32,
        /// Visible monsters off the panel (declared: the panel limit).
        pub monsters_off_panel: u32,
        /// Objects of the gear list, compared with the observed items.
        pub gear_compared: u32,
        pub differences: Vec<String>,
    }

    #[derive(Debug, Default, Serialize)]
    pub struct State {
        pub x: i32,
        pub y: i32,
        pub depth: i32,
        pub max_depth: i32,
        pub hp: i32,
        pub max_hp: i32,
        pub sp: i32,
        pub max_sp: i32,
        pub food: i32,
        pub gold: i32,
        pub exp: i32,
        pub level: i32,
        /// Timed effects other than food that are on, as (index, value).
        pub timed: Vec<(usize, i16)>,
    }

    /// The feature the player remembers at a grid, as `map_info` shows it
    /// (a mimic shows as what it mimics), or 0 if unknown.
    unsafe fn remembered(p: &b::player, grid: b::loc) -> u32 {
        let sq = b::square(p.cave, grid);
        if sq.is_null() {
            return 0;
        }
        let feat = (*sq).feat as usize;
        let f = b::f_info.add(feat);
        if !(*f).mimic.is_null() {
            (*f).mimic.offset_from(b::f_info) as u32
        } else {
            feat as u32
        }
    }

    /// Where an item is: an equipment slot (by its index in the body), the
    /// quiver or the pack.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    enum Place {
        Equipment(usize),
        Quiver,
        Pack,
    }

    /// What an item is, read from the engine's object directly, not through
    /// `analyze` (M2 reviews): the raw identity, the kind's level, and the
    /// known combat values (`obj->known`): ac, to-hit, to-dam, to-ac, dice.
    type Fields = (u32, u8, u8, u8, i16, i32, [i16; 4], [u8; 2]);

    fn direct_fields(i: &Item) -> Fields {
        (
            i.kind,
            i.tval,
            i.sval,
            i.number,
            i.timeout,
            i.level,
            [i.ac, i.to_h, i.to_d, i.to_a],
            [i.dd, i.ds],
        )
    }

    unsafe fn engine_fields(o: &b::object) -> Option<Fields> {
        if o.kind.is_null() || o.known.is_null() {
            return None;
        }
        let k = &*o.known;
        Some((
            (*o.kind).kidx,
            o.tval,
            o.sval,
            o.number,
            o.timeout,
            (*o.kind).level,
            [k.ac, k.to_h, k.to_d, k.to_a],
            [k.dd, k.ds],
        ))
    }

    /// The items of `a` not matched in `b`, counting repeats (M2
    /// re-review, R4: a duplicate is a difference).
    fn missing<T: PartialEq + Clone>(a: &[T], b: &[T]) -> Vec<T> {
        let mut left = b.to_vec();
        a.iter()
            .filter(|x| match left.iter().position(|y| y == *x) {
                Some(n) => {
                    left.remove(n);
                    false
                }
                None => true,
            })
            .cloned()
            .collect()
    }

    /// Every think gives a report, so tools/check-perception.py can require
    /// one line per decision (M2 review, finding 4).
    pub fn check(o: &Observation, w: &World) -> Report {
        // SAFETY: as perceive(): engine globals on the engine thread between
        // game steps; every grid is bounds-checked against the level, every
        // monster index is below `mon_max`, and the gear list is the
        // engine's own linked list.
        unsafe {
            let (p, c, z) = (b::player, b::cave, b::z_info);
            if p.is_null()
                || c.is_null()
                || z.is_null()
                || (*p).cave.is_null()
                || b::f_info.is_null()
            {
                return Report {
                    turn: o.turn,
                    differences: vec!["truth: the engine has no player, level or data".to_string()],
                    ..Report::default()
                };
            }
            let pl = &*p;
            let s = &o.status;
            let mut r = Report {
                turn: o.turn,
                state: State {
                    x: s.x,
                    y: s.y,
                    depth: s.depth,
                    max_depth: s.max_depth,
                    hp: s.hp,
                    max_hp: s.max_hp,
                    sp: s.sp,
                    max_sp: s.max_sp,
                    food: s.food,
                    gold: s.gold,
                    exp: s.exp,
                    level: s.level,
                    timed: s
                        .timed
                        .iter()
                        .enumerate()
                        .filter(|&(i, &v)| i != b::TMD_FOOD as usize && v != 0)
                        // The hallucination test forces TMD_IMAGE while it
                        // perceives (engine::while_hallucinating), so the
                        // observation has it and state.log does not.
                        .filter(|&(i, _)| {
                            !cfg!(feature = "test-hallucinate") || i != b::TMD_IMAGE as usize
                        })
                        .map(|(i, &v)| (i, v))
                        .collect(),
                },
                ..Report::default()
            };
            let mut diffs = Vec::new();

            // The panel: the observation's geometry against the engine's own
            // panel test (M2 review, finding 2: the observation cannot
            // certify its own exceptions). The player is always on it.
            let (lw, lh) = ((*c).width, (*c).height);
            let pn = &o.panel;
            let observed_panel = |x: i32, y: i32| {
                x >= pn.x0 && y >= pn.y0 && x < pn.x0 + pn.width && y < pn.y0 + pn.height
            };
            let engine_panel = |x: i32, y: i32| b::panel_contains(y as u32, x as u32);
            let mut panel_mismatch = 0;
            for y in 0..lh {
                for x in 0..lw {
                    let e = engine_panel(x, y);
                    if e {
                        r.panel_grids += 1;
                    }
                    if e != observed_panel(x, y) {
                        panel_mismatch += 1;
                    }
                }
            }
            if panel_mismatch > 0 {
                diffs.push(format!(
                    "panel: {panel_mismatch} grids differ from the engine's panel (observed {}x{} at {},{})",
                    pn.width, pn.height, pn.x0, pn.y0
                ));
            }
            if !engine_panel(pl.grid.x, pl.grid.y) {
                diffs.push(format!(
                    "panel: the player at ({},{}) is off the engine's panel",
                    pl.grid.x, pl.grid.y
                ));
            }
            if (pn.level_width, pn.level_height) != (lw, lh) {
                diffs.push(format!(
                    "panel: the observed level is {}x{}, the engine's {lw}x{lh}",
                    pn.level_width, pn.level_height
                ));
            }

            // The map: every grid the world remembers against the player's
            // memory; on the panel, also every grid the player knows.
            if (w.level.width, w.level.height) != (lw, lh) {
                diffs.push(format!(
                    "map: the world's level is {}x{}, the engine's {lw}x{lh}",
                    w.level.width, w.level.height
                ));
            } else {
                for y in 0..lh {
                    for x in 0..lw {
                        let grid = b::loc { x, y };
                        if !b::square_in_bounds_fully(c, grid) {
                            continue;
                        }
                        let truth = remembered(pl, grid);
                        let world = w.level.at(x, y).map_or(0, |g| g.feat);
                        let on = engine_panel(x, y);
                        if world == 0 {
                            if truth != 0 {
                                if on {
                                    diffs.push(format!("map: ({x},{y}) on the panel, the player knows {truth}, the world nothing"));
                                } else {
                                    r.map_unknown_to_world += 1;
                                }
                            }
                            continue;
                        }
                        r.map_compared += 1;
                        if world != truth {
                            if on {
                                diffs.push(format!("map: ({x},{y}) the world remembers {world}, the player {truth}"));
                            } else {
                                r.map_stale_off_panel += 1;
                            }
                        }
                    }
                }
            }
            // An unknown grid says nothing about shops and webs (finding 1),
            // and both follow the C Borg's guards.
            for (n, g) in pn.grids.iter().enumerate() {
                let (x, y) = (
                    pn.x0 + n as i32 % pn.width.max(1),
                    pn.y0 + n as i32 / pn.width.max(1),
                );
                if g.shop >= 0 && (g.feat == 0 || !b::feat_is_shop(g.feat as c_int)) {
                    diffs.push(format!(
                        "map: ({x},{y}) a shop on a feature {} that is no known shop",
                        g.feat
                    ));
                }
                if g.webbed && g.feat != b::FEAT_FLOOR {
                    diffs.push(format!(
                        "map: ({x},{y}) a web on a feature {} that is no known floor",
                        g.feat
                    ));
                }
            }

            // Monsters: the engine's visible monsters on the panel are
            // exactly the monsters seen, field by field (finding 3).
            let mut visible = Vec::new();
            for i in 1..i32::from((*c).mon_max) {
                let m = b::cave_monster(c, i);
                if m.is_null() || (*m).race.is_null() || !b::monster_is_visible(m) {
                    continue;
                }
                let m = &*m;
                if engine_panel(m.grid.x, m.grid.y) {
                    visible.push((
                        m.midx,
                        (*m.race).ridx,
                        m.grid.x,
                        m.grid.y,
                        m.hp as i32,
                        m.maxhp as i32,
                        m.m_timed,
                        m.mspeed,
                        m.attr,
                        !m.mimicked_obj.is_null(),
                    ));
                } else {
                    r.monsters_off_panel += 1;
                }
            }
            r.monsters_compared = visible.len() as u32;
            let mut seen: Vec<_> = o
                .monsters
                .iter()
                .map(|m| {
                    (
                        m.index,
                        m.race,
                        m.x,
                        m.y,
                        m.hp,
                        m.max_hp,
                        m.timed,
                        m.speed,
                        m.attr,
                        m.mimicking,
                    )
                })
                .collect();
            visible.sort_unstable();
            seen.sort_unstable();
            for v in missing(&visible, &seen) {
                diffs.push(format!("monsters: visible, not seen as such: {v:?}"));
            }
            for m in missing(&seen, &visible) {
                diffs.push(format!("monsters: seen, not visible as such: {m:?}"));
            }

            // Gear (M2 reviews, R1 and the third review's 2-3): each object
            // of the engine's gear list is placed through the engine's own
            // functions (equipped_item_slot, object_is_in_quiver), paired
            // with the observed item at that place and position, and
            // compared two ways:
            // - field by field, read from the object directly: kind, tval,
            //   sval, number, timeout, the kind's level, the known combat
            //   values;
            // - whole, against analyze() of that very object: weight
            //   (curses included), flags, modifiers, elements, description,
            //   awareness and runes. These use the same engine functions as
            //   perception, so they check that each item is the right
            //   object's, complete and in its place, not the functions.
            // The body's slot count and types are checked against the
            // race's static body (`bodies[race->body]`, which birth copies:
            // player-birth.c:376-381), and the empty slots against the
            // engine's.
            let body = &pl.body;
            if !b::bodies.is_null() && !pl.race.is_null() {
                let model = &*b::bodies.add((*pl.race).body as usize);
                if o.equipment.len() != usize::from(model.count) || body.count != model.count {
                    diffs.push(format!(
                        "equipment: {} slots observed, the body has {}, the race's body {}",
                        o.equipment.len(),
                        body.count,
                        model.count
                    ));
                }
                for (n, s) in o
                    .equipment
                    .iter()
                    .enumerate()
                    .take(usize::from(model.count))
                {
                    let t = (*model.slots.add(n)).type_;
                    if s.slot_type != t {
                        diffs.push(format!(
                            "equipment: slot {n} observed as type {}, the race's body has {t}",
                            s.slot_type
                        ));
                    }
                }
            }
            let mut placed: Vec<(Place, usize, *const b::object)> = Vec::new();
            let mut obj = pl.gear;
            while !obj.is_null() {
                let slot = b::equipped_item_slot(pl.body, obj);
                let place = if slot >= 0 && (slot as u16) < body.count {
                    Place::Equipment(slot as usize)
                } else if b::object_is_in_quiver(p, obj) {
                    Place::Quiver
                } else {
                    Place::Pack
                };
                // The position in the quiver or pack: the observation lists
                // them in the order of the engine's arrays.
                let index = |arr: *mut *mut b::object, n: usize| {
                    (0..n).position(|i| *arr.add(i) == obj).unwrap_or(n)
                };
                let order = match place {
                    Place::Equipment(n) => n,
                    Place::Quiver => index(
                        pl.upkeep
                            .as_ref()
                            .map_or(core::ptr::null_mut(), |u| u.quiver),
                        usize::from((*z).quiver_size),
                    ),
                    Place::Pack => index(
                        pl.upkeep
                            .as_ref()
                            .map_or(core::ptr::null_mut(), |u| u.inven),
                        usize::from((*z).pack_size) + 1,
                    ),
                };
                placed.push((place, order, obj));
                obj = (*obj).next;
            }
            placed.sort_by_key(|&(place, order, _)| (place, order));
            r.gear_compared = placed.len() as u32;
            let occupied: Vec<usize> = o
                .equipment
                .iter()
                .enumerate()
                .filter(|(_, s)| s.item.is_some())
                .map(|(n, _)| n)
                .collect();
            let worn: Vec<usize> = placed
                .iter()
                .filter_map(|&(pl, _, _)| match pl {
                    Place::Equipment(n) => Some(n),
                    _ => None,
                })
                .collect();
            if occupied != worn {
                diffs.push(format!(
                    "equipment: observed occupied slots {occupied:?}, the engine's {worn:?}"
                ));
            }
            let observed_at = |place: Place, k: usize| -> Option<&Item> {
                match place {
                    Place::Equipment(n) => o.equipment.get(n).and_then(|s| s.item.as_ref()),
                    Place::Quiver => o.quiver.get(k),
                    Place::Pack => o.inventory.get(k),
                }
            };
            let (mut quivered, mut packed) = (0, 0);
            for &(place, _, obj) in &placed {
                let k = match place {
                    Place::Quiver => {
                        quivered += 1;
                        quivered - 1
                    }
                    Place::Pack => {
                        packed += 1;
                        packed - 1
                    }
                    Place::Equipment(_) => 0,
                };
                let Some(seen) = observed_at(place, k) else {
                    diffs.push(format!(
                        "gear: {place:?} #{k}: the engine has an object, the observation none"
                    ));
                    continue;
                };
                match engine_fields(&*obj) {
                    Some(f) if f == direct_fields(seen) => {}
                    Some(f) => diffs.push(format!(
                        "gear: {place:?} #{k}: observed {:?}, the object {f:?}",
                        direct_fields(seen)
                    )),
                    None => diffs.push(format!(
                        "gear: {place:?} #{k}: an object without kind or known part"
                    )),
                }
                if super::analyze(obj, false).as_ref() != Some(seen) {
                    diffs.push(format!("gear: {place:?} #{k}: the observed item is not this object's analysis ({})", seen.desc));
                }
            }
            if o.quiver.len() != quivered || o.inventory.len() != packed {
                diffs.push(format!(
                    "gear: observed {} in the quiver and {} in the pack, the engine's gear list {quivered} and {packed}",
                    o.quiver.len(),
                    o.inventory.len()
                ));
            }
            let slot = i32::from((*z).quiver_slot_size).max(1);
            let ammo: i32 = o
                .quiver
                .iter()
                .map(|i| {
                    i32::from(i.number)
                        * if AMMO.contains(&i.tval) {
                            1
                        } else {
                            i32::from((*z).thrown_quiver_mult)
                        }
                })
                .sum();
            let pack = o.inventory.len() as i32 + (ammo + slot - 1) / slot;
            let engine_pack = b::pack_slots_used(p);
            if pack != engine_pack {
                diffs.push(format!(
                    "pack: {pack} slots from the observed items, the engine counts {engine_pack}"
                ));
            }
            if s.pack_used != engine_pack {
                diffs.push(format!(
                    "pack: the observation says {} slots, the engine counts {engine_pack}",
                    s.pack_used
                ));
            }
            r.differences = diffs;
            r
        }
    }
}

/// Whether a spell's effect list feeds the character (`EF_NOURISH`).
///
/// # Safety
/// `effect` is null or the head of a spell's effect list.
unsafe fn spell_nourishes(mut effect: *mut b::effect) -> bool {
    while !effect.is_null() {
        if u32::from((*effect).index) == b::EF_NOURISH {
            return true;
        }
        effect = (*effect).next;
    }
    false
}

/// A spell's first damaging effect, its dice evaluated without a roll
/// (`z-dice.c:dice_random_value:506`, expressions only; `dice_roll` would
/// draw from the game's generator, RULES 10).
///
/// # Safety
/// `effect` is null or the head of a spell's effect list.
unsafe fn spell_damage(mut effect: *mut b::effect) -> Option<crate::observation::SpellDamage> {
    while !effect.is_null() {
        let e = &*effect;
        let name = match u32::from(e.index) {
            b::EF_BOLT => "BOLT",
            b::EF_BOLT_OR_BEAM => "BOLT_OR_BEAM",
            b::EF_BALL => "BALL",
            b::EF_ARC => "ARC",
            b::EF_SHORT_BEAM => "SHORT_BEAM",
            b::EF_STRIKE => "STRIKE",
            b::EF_LINE => "LINE",
            b::EF_SPOT => "SPOT",
            _ => "",
        };
        if !name.is_empty() && !e.dice.is_null() {
            let mut v = b::random_value {
                base: 0,
                dice: 0,
                sides: 0,
                m_bonus: 0,
            };
            b::dice_random_value(e.dice, &mut v);
            return Some(crate::observation::SpellDamage {
                effect: name.to_string(),
                element: e.subtype,
                radius: e.radius,
                base: v.base,
                dice: v.dice,
                sides: v.sides,
            });
        }
        effect = e.next;
    }
    None
}
